lessons.code:
string? raw = Console.ReadLine();
bool valid = int.TryParse(raw, out int seats);
int available = 6;
if (!valid)
{
    Console.WriteLine("أدخل عددًا صحيحًا");
}
else if (seats <= 0)
{
    Console.WriteLine("العدد يبدأ من 1");
}
else if (seats > available)
{
    Console.WriteLine("المقاعد غير كافية");
}
else
{
    Console.WriteLine("تم الحجز: " + seats);
}

